                String inverse = new StringBuilder(substring).reverse().toString();

                // Check if the substring or its inverse is in the map
                if (substringMap.containsKey(substring) || substringMap.containsKey(inverse)) {
                    maxLen = Math.max(maxLen, substring.length());
                }
            }
        }
    }

    return maxLen;
}

