    int count = 0;
    int[] dr = {0, 0, 1, 1, -1, -1, 1, -1};
    int[] dc = {1, -1, 0, 1, 0, -1, 1, -1};
    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            if (grid[i][j] == '@') {
