        for (int i = 0; i < numbers.length; i++) {
            int target = numbers[i] / 2;
            // Check if numbers[i] is even so that target is an integer
            // and if target exists in the list (and is not the same element if target == numbers[i]/2 but we need a different item)
            if (numbers[i] % 2 == 0) {
                for (int j = 0; j < numbers.length; j++) {
                    if (i != j && numbers[j] == target) {
                        count++;
                        break;
                    }
                }
            } else {
                // If numbers[i] is odd, it cannot be exactly double of an integer in the list
                // unless we consider that the problem implies integer division, but typically "twice" means exact double.
                // Given the examples, 8 is twice 4, 10 is twice 5. 
                // If the number is odd, it cannot be 2 * integer.
                // So we don't count it.
            }
        }
        return count;
    }

public static int countDoubles(int[] numbers) {
    if (numbers == null || numbers.length == 0) {
        return 0;
    }

    // Use a HashSet to store all unique numbers for O(1) lookup
    java.util.Set<Integer> numberSet = new java.util.HashSet<>();
    for (int num : numbers) {
        numberSet.add(num);
    }

    int count = 0;
    // Count how many numbers are twice some other number in the set
    for (int num : numbers) {
        if (num % 2 == 0 && numberSet.contains(num / 2)) {
            count++;
        }
    }

    return count;
}

