public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (n <= 0 || start == null || start.length != 2 || end == null || end.length != 2) {
        return "cannot be travelled";
    }

    // Build adjacency list using a map of pairs
    Map<String, List<String>> graph = new HashMap<>();

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            graph.put(i + "," + j, new ArrayList<>());
        }
    }

    // Add paths (undirected)
    if (paths != null) {
        for (int[] path : paths) {
            if (path == null || path.length < 4) {
                continue;
            }
            int x1 = path[0], y1 = path[1], x2 = path[2], y2 = path[3];
            if (x1 >= 0 && x1 < n && y1 >= 0 && y1 < n && x2 >= 0 && x2 < n && y2 >= 0 && y2 < n) {
                String node1 = x1 + "," + y1;
                String node2 = x2 + "," + y2;
                if (graph.containsKey(node1) && graph.containsKey(node2)) {
                    graph.get(node1).add(node2);
                    graph.get(node2).add(node1);
                }
            }
        }
    }

    // BFS to check if end is reachable from start
    int[] sx = start[0], sy = start[1];
    String startNode = sx + "," + sy;

    if (!graph.containsKey(startNode)) {
        return "cannot be travelled";
    }

    Set<String> visited = new HashSet<>();
    Queue<String> queue = new LinkedList<>();
    queue.offer(startNode);
    visited.add(startNode);

    String[] directions = {
        "0,1", "0,-1", "1,0", "-1,0"
    };

    while (!queue.isEmpty()) {
        String current = queue.poll();
        String[] parts = current.split(",");
        int cx = Integer.parseInt(parts[0]);
        int cy = Integer.parseInt(parts[1]);

        // Check neighbors
        for (String dir : directions) {
            String[] dparts = dir.split(",");
            int dx = Integer.parseInt(dparts[0]);
            int dy = Integer.parseInt(dparts[1]);
            int nx = cx + dx;
            int ny = cy + dy;

            if (nx >= 0 && nx < n && ny >= 0 && ny < n) {
                String neighbor = nx + "," + ny;
                if (graph.containsKey(neighbor) && !visited.contains(neighbor)) {
                    // Check if there is an edge between current and neighbor
                    boolean hasEdge = false;
                    for (String adj : graph.get(current)) {
                        if (adj.equals(neighbor)) {
                            hasEdge = true;
                            break;
                        }
                    }
                    if (hasEdge && !visited.contains(neighbor)) {
                        if (nx == end[0] && ny == end[1]) {
                            return "can be travelled";
                        }
                        visited.add(neighbor);
                        queue.offer(neighbor);
                    }
                }
            }
        }
    }

    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Create adjacency list
    List<List<Integer>> adjList = new ArrayList<>();
    for (int i = 0; i < n; i++) {
        adjList.add(new ArrayList<>());
    }

    // Fill adjacency list from paths
    for (int[] path : paths) {
        int u = path[0];
        int v = path[1];
        adjList.get(u).add(v);
        adjList.add(v).add(u); // Assuming undirected paths
    }

    // BFS to check if path exists from start to end
    int startNode = start[0];
    int endNode = end[0];

    // Boolean array to track visited nodes
    boolean[] visited = new boolean[n];
    Queue<Integer> queue = new LinkedList<>();

    // Start BFS from the start node
    queue.add(startNode);
    visited[startNode] = true;

    while (!queue.isEmpty()) {
        int current = queue.poll();

        // If we reached the end node, return "can be travelled"
        if (current == endNode) {
            return "can be travelled";
        }

        // Visit all adjacent nodes
        for (int neighbor : adjList.get(current)) {
            if (!visited[neighbor]) {
                visited[neighbor] = true;
                queue.add(neighbor);
            }
        }
    }

    // If queue is empty and we never reached the end, travel is not possible
    return "cannot be travelled";
}

public static String appx(String word1, String word2) {
        // Count common letters
        Map<Character, Integer> freq1 = new HashMap<>();
        Map<Character, Integer> freq2 = new HashMap<>();

        for (char c : word1.toCharArray()) {
            freq1.put(c, freq1.getOrDefault(c, 0) + 1);
        }
        for (char c : word2.toCharArray()) {
            freq2.put(c, freq2.getOrDefault(c, 0) + 1);
        }

        int commonCount = 0;
        for (Map.Entry<Character, Integer> entry : freq1.entrySet()) {
            char c = entry.getKey();
            if (freq2.containsKey(c)) {
                commonCount += Math.min(entry.getValue(), freq2.get(c));
            }
        }

        int sumLengths = word1.length() + word2.length();

        // Reduce the fraction
        int gcd = gcd(commonCount, sumLengths);
        commonCount /= gcd;
        sumLengths /= gcd;

        // Format the result
        String result;
        if (sumLengths == 1) {
            result = commonCount + "";
        } else {
            result = commonCount + "/" + sumLengths;
        }

        return "appx(" + word1 + ", " + word2 + ") = " + result;
    }

public static String appx(String word1, String word2) {
    if (word1 == null || word2 == null) {
        return "Error: Input words cannot be null.";
    }

    // Count frequency of each character in word1
    int[] freq1 = new int[26];
    for (char c : word1.toCharArray()) {
        if (c >= 'A' && c <= 'Z') {
            freq1[c - 'A']++;
        } else if (c >= 'a' && c <= 'z') {
            freq1[c - 'a']++;
        }
    }

    // Count common letters by iterating through word2
    int commonCount = 0;
    for (char c : word2.toCharArray()) {
        int idx;
        if (c >= 'A' && c <= 'Z') {
            idx = c - 'A';
        } else if (c >= 'a' && c <= 'z') {
            idx = c - 'a';
        } else {
            continue; // Non-alphabetic characters are ignored
        }

        if (freq1[idx] > 0) {
            commonCount++;
            freq1[idx]--;
        }
    }

    int totalLength = word1.length() + word2.length();

    if (totalLength == 0) {
        return "appx(" + word1 + ", " + word2 + ") = 0";
    }

    if (commonCount == 0) {
        return "appx(" + word1 + ", " + word2 + ") = 0";
    }

    // Reduce the fraction commonCount / totalLength
    int gcd = gcd(commonCount, totalLength);
    int numerator = commonCount / gcd;
    int denominator = totalLength / gcd;

    if (denominator == 1) {
        return "appx(" + word1 + ", " + word2 + ") = " + numerator;
    } else {
        return "appx(" + word1 + ", " + word2 + ") = " + numerator + "/" + denominator;
    }
}

