public static String convertDatesToWeekdays(String date) {
    if (date == null || date.trim().isEmpty()) {
        return "Invalid date format";
    }

    java.text.SimpleDateFormat parser = new java.text.SimpleDateFormat("MM dd yyyy");
    parser.setLenient(false);

    java.util.Date parsedDate;
    try {
        parsedDate = parser.parse(date.trim());
    } catch (java.text.ParseException e) {
        return "Invalid date format";
    }

    java.text.SimpleDateFormat format = new java.text.SimpleDateFormat("MMMM d, yyyy");
    String formattedDate = format.format(parsedDate);

    java.util.Calendar calendar = java.util.Calendar.getInstance();
    calendar.setTime(parsedDate);
    int dayOfWeek = calendar.get(java.util.Calendar.DAY_OF_WEEK);

    String[] weekdays = {"Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"};
    String weekday = weekdays[dayOfWeek - 1];

    return formattedDate + " is a " + weekday;
}

