public static String convertDatesToWeekdays(String date) {
    if (date == null || date.trim().isEmpty()) {
        throw new IllegalArgumentException("Date string cannot be null or empty");
    }

    String[] parts = date.trim().split("\\s+");
    if (parts.length != 3) {
        throw new IllegalArgumentException("Date string must be in the format 'MM dd yyyy'");
    }

    int month = Integer.parseInt(parts[0]);
    int day = Integer.parseInt(parts[1]);
    int year = Integer.parseInt(parts[2]);

    String[] monthNames = {"January", "February", "March", "April", "May", "June",
                           "July", "August", "September", "October", "November", "December"};

    if (month < 1 || month > 12 || day < 1 || day > 31) {
        throw new IllegalArgumentException("Invalid date");
    }

    java.util.Calendar calendar = java.util.Calendar.getInstance();
    calendar.clear();
    calendar.set(year, month - 1, day);

    int weekdayIndex = calendar.get(java.util.Calendar.DAY_OF_WEEK);
    String[] weekdayNames = {"Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"};
    // Calendar.SUNDAY is 1, Calendar.SATURDAY is 7
    String weekday = weekdayNames[weekdayIndex - 1];

    String fullDate = monthNames[month - 1] + " " + day + ", " + year;

    return fullDate + " is a " + weekday;
}

