public boolean canArrange(int[] arr, int k) {
    if (arr == null || arr.length % 2 != 0) {
        return false;
    }

    int[] remainderCount = new int[k];

    for (int num : arr) {
        int remainder = ((num % k) + k) % k;
        remainderCount[remainder]++;
    }

    if (remainderCount[0] % 2 != 0) {
        return false;
    }

    for (int i = 1; i <= k / 2; i++) {
        int complement = k - i;
        if (i == complement) {
            if (remainderCount[i] % 2 != 0) {
                return false;
            }
        } else {
            if (remainderCount[i] != remainderCount[complement]) {
                return false;
            }
        }
    }

    return true;
}

