public boolean canArrange(int[] arr, int k) {
    if (arr == null || arr.length == 0) {
        return true;
    }

    int n = arr.length;
    // If the number of elements is odd, we can't form pairs
    if (n % 2 != 0) {
        return false;
    }

    int[] remainderCount = new int[k];

    // Count the number of elements with each remainder
    for (int num : arr) {
        int remainder = num % k;
        // Handle negative remainders
        if (remainder < 0) {
            remainder += k;
        }
        remainderCount[remainder]++;
    }

    // The count of elements with remainder 0 must be even
    if (remainderCount[0] % 2 != 0) {
        return false;
    }

    // For each remainder pair (i, k-i), the count must be equal
    int half = k / 2;
    for (int i = 1; i <= half; i++) {
        int j = k - i;
        // If i and j are the same (which happens when k is even and i == j == k/2),
        // the count must be even
        if (i == j) {
            if (remainderCount[i] % 2 != 0) {
                return false;
            }
        } else {
            // Otherwise, the counts must be equal
            if (remainderCount[i] != remainderCount[j]) {
                return false;
            }
        }
    }

    return true;
}

