public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        return s;
    }

    int[] count = new int[26];
    for (char c : s.toCharArray()) {
        count[c - 'a']++;
    }

    int n = s.length();
    char[] result = new char[n];
    int resultIndex = 0;
    int remaining = n;

    while (remaining > 0) {
        // Steps 1-3: Pick smallest to largest, strictly increasing
        for (int i = 0; i < 26 && remaining > 0; i++) {
            if (count[i] > 0) {
                result[resultIndex++] = (char) ('a' + i);
                count[i]--;
                remaining--;
            }
        }

        // Steps 4-6: Pick largest to smallest, strictly decreasing
        for (int i = 25; i >= 0 && remaining > 0; i--) {
            if (count[i] > 0) {
                result[resultIndex++] = (char) ('a' + i);
                count[i]--;
                remaining--;
            }
        }
    }

    return new String(result);
}

