public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    int totalSum = 0;
    for (int num : nums) {
        totalSum += num;
    }

    // The average of a subset of size k must be totalSum / n
    // So sum of subset = k * totalSum / n
    // For this to be integer, k * totalSum must be divisible by n
    // Also, the complement subset (size n-k) must have the same average.

    // By symmetry, we only need to check subset sizes from 1 to n/2 (inclusive)
    // Because if a subset of size k works, the complement of size n-k also works.
    // Also, due to gcd simplification, valid subset sizes k must satisfy:
    // (k * totalSum) % n == 0

    for (int k = 1; k <= n / 2; k++) {
        if ((long) k * totalSum % n != 0) {
            continue;
        }
        int targetSum = k * totalSum / n;
        if (canPickSubsetWithSum(nums, k, targetSum)) {
            return true;
        }
    }
    return false;
}

