    }

    int totalSum = 0;
    for (int num : nums) {
        totalSum += num;
    }

    // The average of the original array is totalSum / n
    // We need to find a subset of size k (1 <= k <= n-1) such that
    // sum(subset) / k == totalSum / n
    // This is equivalent to sum(subset) * n == totalSum * k

    int gcd = totalSum;
    int g = n;
    while (g != 0) {
        int temp = g;
        g = gcd % g;
        gcd = temp;
    }

    int reducedN = n / gcd;
    int reducedDiv = totalSum / gcd;

    for (int k = 1; k <= n / 2; k++) {
        if (reducedDiv * k % reducedN == 0) {
            // Check if we can form a subset of size k with sum = totalSum * k / n
            int targetSum = (totalSum * k) / n;
