public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        return 0;
    }
    if (cost.length == 1) {
        return cost[0];
    }

    int n = cost.length;
    int prev2 = 0;
    int prev1 = 0;

    for (int i = 0; i < n; i++) {
        int current = Math.min(prev1, prev2) + cost[i];
        prev2 = prev1;
        prev1 = current;
    }

    return Math.min(prev1, prev2);
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
