    }

    int n = cost.length;
    if (n == 1) {
        return cost[0];
    }

    // dp[i] represents the minimum cost to reach step i
    // You can start from index 0 or index 1, with no additional cost to start
    // To reach index i, you can come from i-1 or i-2
    // If you are at index i, you pay cost[i] to stand there

    // Base case:
    // dp[0] = cost[0] (start from 0)
    // dp[1] = cost[1] (start from 1)

    // We need to reach the top, which is index n (beyond the last step)
    // To reach index n, you can come from n-1 or n-2

    int[] dp = new int[n + 1];
    dp[0] = 0;
    dp[1] = 0;

    for (int i = 2; i <= n; i++) {
        dp[i] = Math.min(dp[i - 1] + cost[i - 1], dp[i - 2] + cost[i - 2]);
    }

    return dp[n];
}

