    for (int i = 0; i < k; i++) {
        windowValue = (windowValue << 1) | (s.charAt(i) - '0');
    }

    if (!seen[windowValue]) {
        seen[windowValue] = true;
        count++;
        if (count == total) {
            return true;
        }
    }

    // Slide the window
    for (int i = k; i < s.length(); i++) {
        windowValue = ((windowValue << 1) & (total - 1)) | (s.charAt(i) - '0');
        if (!seen[windowValue]) {
            seen[windowValue] = true;
            count++;
            if (count == total) {
                return true;
            }
        }
    }

    return false;
}

