public int minOperations(int n) {
    if (n <= 0) {
        return 0;
    }

    // The array is: 1, 3, 5, ..., 2*(n-1)+1 = 2n-1
    // The sum of the array is sum of first n odd numbers = n^2
    // The average is n^2 / n = n
    // So we want to make all elements equal to n

    // The number of operations is the sum of |arr[i] - n| for all i where arr[i] > n
    // (or equivalently, the sum for arr[i] < n, since total deficit equals total surplus)

    // arr[i] = 2*i + 1
    // We need to find how many elements are greater than n
    // 2*i + 1 > n  =>  i > (n-1)/2

    long operations = 0;
    for (int i = 0; i < n; i++) {
        int value = 2 * i + 1;
        if (value > n) {
            // surplus: value - n
            operations += (value - n);
        }
    }

    return (int) operations;
}

public int minOperations(int n) {
    // The array arr has arr[i] = 2*i + 1 for 0 <= i < n
    // We need to make all elements equal.
    // The sum of the array is: sum = 1 + 3 + 5 + ... + (2*n - 1) = n * n
    // The target value when all are equal is target = n * n / n = n

    // We need to find the minimum number of operations to make all elements equal to n.
    // Each operation moves 1 unit from one element to another.
    // The total number of operations is half the sum of absolute differences between each element and the target.
    // But since each operation transfers 1 unit from one element to another, 
    // the total number of operations is the sum of the amounts that need to be added to elements below target.
    // (or equivalently, the sum of amounts that need to be removed from elements above target)

    // For arr[i] = 2*i + 1:
    // If arr[i] < target (i.e., 2*i + 1 < n), we need to add (target - arr[i]) to it.
    // If arr[i] > target, we need to subtract (arr[i] - target) from it.

    // The total operations = sum of (target - arr[i]) for all i where arr[i] < target

    // Let's compute this:
    // target = n
    // arr[i] = 2*i + 1
    // We need 2*i + 1 < n, i.e., i < (n-1)/2

    // For a given i where arr[i] < n:
    // operations_i = n - (2*i + 1)

    // Sum over i from 0 to floor((n-2)/2) [since 2*i+1 < n means i < (n-1)/2, 
    // and since i is integer, i <= (n-2)/2 when n is even or odd]

    // Actually, let's just loop and compute.

    int target = n;
    int operations = 0;

    for (int i = 0; i < n; i += 2) {
        int arr_i = 2 * i + 1;
        if (arr_i < target) {
            operations += (target - arr_i);
        }
    }

    return operations;
}

public int minOperations(int n) {
    // arr[i] = 2*i + 1
    // Target value is n (average of the array)
    // Sum of differences from target for the lower half
    // For n=3: target=3, lower elements: arr[0]=1, diff=2; arr[1]=3, diff=0. MinOps=2
    // For n=6: target=6, lower elements: arr[0]=1(diff5), arr[1]=3(diff3), arr[2]=5(diff1). MinOps=9

    // Using the derived formula
    if (n % 2 == 1) {
        // n is odd
        int m = n / 2;
        return n * m;
    } else {
        // n is even
        int m = n / 2;
        return m * m;
    }
}

