public int findMinFibonacciNumbers(int k) {
        if (k <= 0) {
            return 0;
        }

        // Generate Fibonacci numbers up to k
        java.util.List<Integer> fibs = new java.util.ArrayList<>();
        fibs.add(1);
        fibs.add(1);
        int i = 2;
        while (true) {
            int next = fibs.get(i - 1) + fibs.get(i - 2);
            if (next > k) {
                break;
            }
            fibs.add(next);
            i++;
        }

        // Greedy approach: pick the largest Fibonacci number <= remaining k
        int count = 0;
        int idx = fibs.size() - 1;
        while (k > 0 && idx >= 0) {
            if (fibs.get(idx) <= k) {
                k -= fibs.get(idx);
                count++;
            }
            idx--;
        }

        return count;
    }

public int findMinFibonacciNumbers(int k) {
    // Generate Fibonacci numbers up to k
    java.util.Set<Integer> fibs = new java.util.HashSet<>();
    int a = 1, b = 1;
    fibs.add(a);
    while (b <= k) {
        fibs.add(b);
        int temp = a + b;
        a = b;
        b = temp;
    }

    // Use greedy approach: always pick the largest Fibonacci number that is <= remaining k
    // To do this, we can store Fibonacci numbers in a sorted structure or just iterate in reverse
    java.util.TreeSet<Integer> sortedFibs = new java.util.TreeSet<>(fibs);
    sortedFibs.descendingSet();

    int count = 0;
    int remaining = k;
    for (int fib : sortedFibs) {
        if (fib > remaining) {
            continue;
        }
        // Take this Fibonacci number
        count++;
        remaining -= fib;
        if (remaining == 0) {
            break;
        }
    }

    return count;
}

