    }

    int m = mat.length;
    int n = mat[0].length;
    int maxLen = 0;

    // Horizontal DP: dpH[i][j] = length of horizontal line ending at (i, j)
    // Vertical DP: dpV[i][j] = length of vertical line ending at (i, j)
    // Diagonal DP: dpD[i][j] = length of diagonal line ending at (i, j)
    // Anti-diagonal DP: dpAD[i][j] = length of anti-diagonal line ending at (i, j)

    int[][] dpH = new int[m][n];
    int[][] dpV = new int[m][n];
    int[][] dpD = new int[m][n];
    int[][] dpAD = new int[m][n];

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                // Horizontal: if not at first column, add to left
                dpH[i][j] = (j > 0 ? dpH[i][j - 1] : 0) + 1;

                // Vertical: if not at first row, add to above
                dpV[i][j] = (i > 0 ? dpV[i - 1][j] : 0) + 1;

                // Diagonal: if not at first row and first column, add to top-left
                dpD[i][j] = (i > 0 && j > 0 ? dpD[i - 1][j - 1] : 0) + 1;

                // Anti-diagonal: if not at first row and first column, add to top-right
                dpAD[i][j] = (i > 0 && j < n - 1 ? dpAD[i - 1][j + 1] : 0) + 1;

                maxLen = Math.max(maxLen, dpH[i][j]);
                maxLen = Math.max(maxLen, dpV[i][j]);
                maxLen = Math.max(maxLen, dpD[i][j]);
                maxLen = Math.max(maxLen, dpAD[i][j]);
            }
        }
    }

    return maxLen;
}

public static String addThousandSeparator(int n) {
