    if (len <= 3) {
        return num;
    }

    // Handle negative numbers
    if (num.charAt(0) == '-') {
        sb.append('-');
        num = num.substring(1);
        len = num.length();
    }

    // Find the position of the first separator
    int firstSep = len % 3;
    if (firstSep == 0) {
        firstSep = 3;
    }

    // Append the first group of digits
    sb.append(num, 0, firstSep);

    // Append the remaining groups with separators
    for (int i = firstSep; i < len; i += 3) {
        sb.append('.');
        sb.append(num, i, i + 3);
    }

    return sb.toString();
}

