public static List<String> centerSymmetricNumbers(int n) {
    if (n <= 0) {
        return new ArrayList<>();
    }

    List<String> result = new ArrayList<>();

    if (n == 1) {
        result.add("0");
        result.add("1");
        result.add("8");
        return result;
    }

    // Center symmetric characters:
    // 0 <-> 0
    // 1 <-> 1
    // 6 <-> 9
    // 8 <-> 8
    // 9 <-> 6
    char[] symmetricChars = {'0', '1', '6', '8', '9'};
    char[] symmetricReverse = {'0', '1', '9', '8', '6'};

    int halfLen = n / 2;

    // Generate all combinations for the first half
    // The first digit cannot be 0 (unless n == 1, which we handled)
    // So for the first half, the first character can be 0,1,6,8,9 but if it's the first character of the whole number, it can't be 0
    // Wait, actually for n >= 2, the first digit of the entire number cannot be 0.
    // The first half has length halfLen. If halfLen >= 1, the first character of the first half is the first character of the number, so it can't be 0.

    for (int i = 0; i < Math.pow(5, halfLen); i++) {
        StringBuilder firstHalf = new StringBuilder();
        int temp = i;
        for (int j = 0; j < halfLen; j++) {
            int digit = temp % 5;
            firstHalf.append(symmetricChars[digit]);
            temp /= 5;
        }
        firstHalf.reverse();

        // Check if the first character is '0' and n > 1, skip
        if (firstHalf.charAt(0) == '0') {
            continue;
        }

        StringBuilder secondHalf = new StringBuilder();
        for (int j = 0; j < firstHalf.length(); j++) {
            char c = firstHalf.charAt(firstHalf.length() - 1 - j);
            for (int k = 0; k < 5; k++) {
                if (c == symmetricChars[k]) {
                    secondHalf.append(symmetricReverse[k]);
                    break;
                }
            }
        }

        String number = firstHalf.toString() + secondHalf.toString();
        result.add(number);
    }

    return result;
}

