public static int calculateUniqueSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }

    // Use a list to track elements that have appeared once,
    // and a list to track elements that have appeared more than once.
    java.util.List<Integer> uniqueElements = new java.util.ArrayList<>();
    java.util.List<Integer> duplicateElements = new java.util.ArrayList<>();

    for (int num : nums) {
        if (!uniqueElements.contains(num) && !duplicateElements.contains(num)) {
            uniqueElements.add(num);
        } else if (uniqueElements.contains(num)) {
            // This is the second time we see this number, move it to duplicates
            uniqueElements.remove(uniqueElements.indexOf(num));
            duplicateElements.add(num);
        }
        // If it's already in duplicates, we ignore it
    }

    int sum = 0;
    for (int num : uniqueElements) {
        sum += num;
    }

    return sum;
}

