    for (int num : nums) {
        if (seen.contains(num)) {
            unique.remove(num);
        } else {
            unique.add(num);
        }
        seen.add(num);
    }

    int sum = 0;
    for (int num : unique) {
        sum += num;
    }

    return sum;
}

public static int minPerfectSquareSum(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("Input must be a non-negative integer.");
        }
        if (n == 0) {
            return 0;
        }
        // Initialize dp array
        int[] dp = new int[n + 1];
        for (int i = 1; i <= n; i++) {
            dp[i] = i; // worst case: sum of 1s
        }
        // Fill the dp table using bottom-up dynamic programming
        for (int i = 1; i * i <= n; i++) {
            int square = i * i;
            for (int j = square; j <= n; j++) {
                dp[j] = Math.min(dp[j], dp[j - square] + 1);
            }
        }
        return dp[n];
    }

public static int minPerfectSquareSum(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be a positive integer");
        }

        int[] dp = new int[n + 1];
        dp[0] = 0;

        for (int i = 1; i <= n; i++) {
            dp[i] = Integer.MAX_VALUE;
            for (int j = 1; j * j <= i; j++) {
                int square = j * j;
                if (dp[i - square] != Integer.MAX_VALUE) {
                    dp[i] = Math.min(dp[i], dp[i - square] + 1);
                }
            }
        }

        return dp[n];
    }

public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }

    // dp[i] will hold the minimum number of perfect squares needed to sum up to i
    int[] dp = new int[n + 1];
    dp[0] = 0;

    for (int i = 1; i <= n; i++) {
        dp[i] = i; // initialize with worst case (all 1s)
        int j = 1;
        while (j * j <= i) {
            int square = j * j;
            dp[i] = Math.min(dp[i], dp[i - square] + 1);
            j++;
        }
    }

    return dp[n];
}

public static int minPerfectSquareSum(int n) {
    if (n < 0) {
        throw new IllegalArgumentException("Input must be a non-negative integer.");
    }

    // Base cases
    if (n == 0) {
        return 0;
    }

    // Use Legendre's three-square theorem optimization
    // A number can be represented as the sum of three squares if and only if it is not of the form 4^a(8b+7)
    // But we need minimum number of squares (1, 2, 3, or 4)

    // Check if n is a perfect square (answer is 1)
    int sqrtN = (int) Math.sqrt(n);
    if (sqrtN * sqrtN == n) {
        return 1;
    }

    // Check if n can be expressed as sum of two squares (answer is 2)
    for (int i = 1; i * i <= n; i++) {
        int remaining = n - i * i;
        int sqrtRemaining = (int) Math.sqrt(remaining);
        if (sqrtRemaining * sqrtRemaining == remaining) {
            return 2;
        }
    }

    // Check if n can be expressed as sum of three squares using Legendre's three-square theorem
    // n is not of the form 4^a(8b+7)
    int temp = n;
    while (temp % 4 == 0) {
        temp /= 4;
    }
    if (temp % 8 != 7) {
        return 3;
    }

    // Otherwise, answer is 4 (Lagrange's four-square theorem)
    return 4;
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }

    // dp[i] will store the minimum number of perfect square numbers that sum up to i
    int[] dp = new int[n + 1];

    // Initialize with large value (we at most need n 1's)
    for (int i = 1; i <= n; i++) {
        dp[i] = i; // worst case: i ones
    }

    // Precompute perfect squares
    for (int i = 1; i * i <= n; i++) {
        int square = i * i;
        for (int j = square; j <= n; j++) {
            dp[j] = Math.min(dp[j], dp[j - square] + 1);
        }
    }

    return dp[n];
}

public static String reverseWords(String s) {
    if (s == null || s.isEmpty()) {
        return s;
    }

    String[] words = s.split(" ", -1);
    StringBuilder result = new StringBuilder();

    for (int i = 0; i < words.length; i++) {
        String word = words[i];
        StringBuilder reversedWord = new StringBuilder();
        for (int j = word.length() - 1; j >= 0; j--) {
            reversedWord.append(word.charAt(j));
        }
        result.append(reversedWord);
        if (i < words.length - 1) {
            result.append(" ");
        }
    }

    return result.toString();
}

public static String reverseWords(String s) {
    if (s == null || s.isEmpty()) {
        return s;
    }

    String[] words = s.split(" ", -1); // Keep empty strings from multiple spaces
    StringBuilder result = new StringBuilder();

    for (int i = 0; i < words.length; i++) {
        // Reverse the characters in the current word
        char[] chars = words[i].toCharArray();
        int left = 0, right = chars.length - 1;
        while (left < right) {
            char temp = chars[left];
            chars[left] = chars[right];
            chars[right] = temp;
            left++;
            right--;
        }
        result.append(new String(chars));
        if (i < words.length - 1) {
            result.append(" ");
        }
    }

    return result.toString();
}

public static String reverseWords(String s) {
    if (s == null || s.length() == 0) {
        return s;
    }

    StringBuilder result = new StringBuilder();
    int i = 0;

    while (i < s.length()) {
        // Skip spaces
        if (s.charAt(i) == ' ') {
            result.append(' ');
            i++;
        } else {
            // Find the end of the current word
            int start = i;
            while (i < s.length() && s.charAt(i) != ' ') {
                i++;
            }
            // Reverse the word
            String word = s.substring(start, i);
            StringBuilder reversed = new StringBuilder(word).reverse();
            result.append(reversed);
        }
    }

    return result.toString();
}

